{
  "command": "replace_content_by_matching",
  "args": {
    "old_content": "    // Combinational function derived from the given Karnaugh map
    always @(*) begin
        f = ( (~x[3] & ~x[2] & ~x[1]) |
              ( x[3] &  x[2] & ~x[0]) |
              ( x[3] & ~x[2] & ~x[1]) |
              ( x[3] & ~x[2] & ~x[0]) );
    end",
    "new_content": "    // Combinational function derived from the given Karnaugh map
    // Row index is x[2]x[3], column index is x[0]x[1] as stated in the table.
    // Implemented with explicit minterms to avoid bit-ordering mistakes.
    always @(*) begin
        f = 1'b0;
        // Row x[2]x[3] = 00: (x2=0,x3=0) => cols 00 and 10 are 1
        if (x[3] == 1'b0 && x[2] == 1'b0 && x[1] == 1'b0 && x[0] == 1'b0) f = 1'b1; // col 00
        if (x[3] == 1'b0 && x[2] == 1'b0 && x[1] == 1'b1 && x[0] == 1'b0) f = 1'b1; // col 10

        // Row x[2]x[3] = 01: (x2=0,x3=1) => all 0

        // Row x[2]x[3] = 11: (x2=1,x3=1) => cols 00,01,11 are 1
        if (x[3] == 1'b1 && x[2] == 1'b1 && x[1] == 1'b0 && x[0] == 1'b0) f = 1'b1; // col 00
        if (x[3] == 1'b1 && x[2] == 1'b1 && x[1] == 1'b0 && x[0] == 1'b1) f = 1'b1; // col 01
        if (x[3] == 1'b1 && x[2] == 1'b1 && x[1] == 1'b1 && x[0] == 1'b1) f = 1'b1; // col 11

        // Row x[2]x[3] = 10: (x2=1,x3=0) => cols 00,01,11,? per table row 10: 1 1 0 1
        // Mapping: col 00 => (x1=0,x0=0) => 1
        if (x[3] == 1'b0 && x[2] == 1'b1 && x[1] == 1'b0 && x[0] == 1'b0) f = 1'b1;
        // col 01 => (x1=0,x0=1) => 1
        if (x[3] == 1'b0 && x[2] == 1'b1 && x[1] == 1'b0 && x[0] == 1'b1) f = 1'b1;
        // col 11 => (x1=1,x0=1) => 0 (leave as 0)
        // col 10 => (x1=1,x0=0) => 1
        if (x[3] == 1'b0 && x[2] == 1'b1 && x[1] == 1'b1 && x[0] == 1'b0) f = 1'b1;
    end"
  }
}

